import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { log } from 'crawlee';
import type { PropDiff } from './responseEvaluate';

/**
 * Generates a standalone, runnable `.ts` reproduction script for one flagged finding — the output
 * of the analysis pipeline a human tester actually acts on, not an internal test of this project's
 * own code. `npx tsx` on the generated file:
 *  - replays the exact forged request/client-side probe live and prints the real status/similarity
 *    (http) or hasMutatedDom/isUsingNewParams (client-routing) — reproducible, not just asserted;
 *  - re-reads the exact React state snapshot this finding was derived from straight out of
 *    storage/crawler.db and checks each authz-relevant prop difference against it, printing
 *    OK/MISMATCH per property — so "isLocked: true was seen on this node" is something the tester
 *    can confirm against the same persisted evidence this pipeline used, not just a trusted claim;
 *  - prints exact, independent manual-verification steps (open the page with RAPIDOR in 'full'
 *    mode, inspect this node, check this path) for a tester who wants to confirm it without relying
 *    on storage/crawler.db at all.
 *
 * Caveat spelled out in the generated file itself: it reads storage/crawler.db (or whatever db path
 * this run used) by the stateId/nodeIds recorded at generation time. Re-running the crawler with
 * `clearOnStart` (the default) wipes that db, so a report generated by an earlier run can go stale —
 * the React-evidence section degrades gracefully (reports "snapshot not found", does not throw) but
 * the live replay sections (http refetch / client-routing probe) stay fully reproducible regardless,
 * since they only need network/browser access to the real site, not this project's own storage.
 */

export type ReproductionKind =
  | { type: 'http'; method: string; headers: Record<string, string>; postData?: string; baselineStatus: number; baselineHeaders: Record<string, string>; baselineBody: string; baselineContentType?: string }
  | { type: 'client-routing-query'; paramName: string; candidateValue: string }
  | { type: 'client-routing-path'; candidateUrl: string };

export interface ReproductionInput {
  id: string;
  site: string;
  referenceUrl: string;
  candidateUrl: string;
  motivation: string;
  differences: PropDiff[];
  sensitiveKeys: string[];
  stateId: number;
  referenceNodeId: string;
  candidateNodeId: string;
  dbPath: string;
  userDataDir?: string;
  reportsDir: string;
  kind: ReproductionKind;
}

/** JS literal, not JSON.stringify: keeps `undefined` as `undefined` rather than dropping the key silently. */
function literal(value: unknown): string {
  return value === undefined ? 'undefined' : JSON.stringify(value, null, 2);
}

function reproductionBody(input: ReproductionInput): string {
  const { kind } = input;
  if (kind.type === 'http') {
    return `
  const { forgeRequest } = await import('../../src/analysis/requestForge');
  const { getServerResponseSimilarity } = await import('../../src/analysis/responseEvaluate');

  console.log('\\n--- live replay: forging the candidate request ---');
  const forged = await forgeRequest({
    page, url: CANDIDATE_URL, method: ${literal(kind.method)},
    headers: ${literal(kind.headers)}, postData: ${literal(kind.postData)},
  });
  const similarity = getServerResponseSimilarity(
    { status: ${literal(kind.baselineStatus)}, headers: ${literal(kind.baselineHeaders)}, body: ${literal(kind.baselineBody)}, contentType: ${literal(kind.baselineContentType)} },
    forged,
  );
  console.log('candidate response status:', forged.status);
  console.log('similarity to the ORIGINAL (reference) response:', JSON.stringify(similarity, null, 2));
  console.log(similarity.areSimilar
    ? '=> the server answered the candidate request as if it were a normal, successful one (same shape as the reference) — consistent with an IDOR.'
    : '=> NOT similar to the reference response this time (server may have changed, or this needs a fresh crawl) — re-check manually.');
`;
  }
  if (kind.type === 'client-routing-query') {
    return `
  const { checkClientSideRouting } = await import('../../src/analysis/clientRouting');
  const { installParamUsageTracking } = await import('../../src/browser/paramUsageTracker');

  await installParamUsageTracking(page); // must run before the navigation below (it's an init script)
  await page.goto(REFERENCE_URL, { waitUntil: 'load' });

  console.log('\\n--- live replay: client-side routing probe (pushState + popstate) ---');
  const result = await checkClientSideRouting({ page, paramName: ${literal(kind.paramName)}, paramValue: ${literal(kind.candidateValue)} });
  console.log(JSON.stringify(result, null, 2));
  console.log(result.isUsingNewParams
    ? "=> the page's own React routing reacted to the swapped value and read it — consistent with an IDOR (no server round-trip needed to prove this one)."
    : '=> did not reproduce this time (SPA state may have changed, or this needs a fresh crawl) — re-check manually.');
`;
  }
  return `
  const { checkClientSideRoutingForPath } = await import('../../src/analysis/clientRouting');

  await page.goto(REFERENCE_URL, { waitUntil: 'load' });

  console.log('\\n--- live replay: client-side routing probe (pushState + popstate) ---');
  const result = await checkClientSideRoutingForPath({ page, targetUrl: CANDIDATE_URL });
  console.log(JSON.stringify(result, null, 2));
  console.log(result.isUsingNewParams
    ? "=> the page's own React routing reacted to the swapped path segment — consistent with an IDOR (no server round-trip needed to prove this one)."
    : '=> did not reproduce this time (SPA state may have changed, or this needs a fresh crawl) — re-check manually.');
`;
}

function reactEvidenceSection(input: ReproductionInput): string {
  return `
async function checkReactEvidence() {
  console.log('\\n--- React evidence: re-reading the exact snapshot this finding was derived from ---');
  const { openDatabase } = await import('../../src/db/openDatabase');
  const { ReactStateStore } = await import('../../src/db/ReactStateStore');
  const { readPath } = await import('../../src/analysis/matchFinder');

  const db = openDatabase({ path: DB_PATH });
  const reactStateStore = new ReactStateStore({ db, clearOnStart: false });
  const graph = reactStateStore.getById(STATE_ID);
  if (!graph) {
    console.log(\`snapshot \${STATE_ID} is no longer in \${DB_PATH} (the db was reset since this report was generated) — run the crawler again to regenerate it, or verify manually (see below).\`);
    db.close();
    return;
  }

  const refNode = graph.nodes?.[REFERENCE_NODE_ID];
  const candNode = graph.nodes?.[CANDIDATE_NODE_ID];
  for (const diff of DIFFERENCES) {
    const refActual = refNode ? readPath(refNode, diff.path) : undefined;
    const candActual = candNode ? readPath(candNode, diff.path) : undefined;
    const refOk = JSON.stringify(refActual) === JSON.stringify(diff.reference);
    const candOk = JSON.stringify(candActual) === JSON.stringify(diff.current);
    console.log(\`\${refOk && candOk ? 'OK' : 'MISMATCH'} \${diff.pathStr}: reference node \${REFERENCE_NODE_ID} = \${JSON.stringify(refActual)} (recorded: \${JSON.stringify(diff.reference)}), candidate node \${CANDIDATE_NODE_ID} = \${JSON.stringify(candActual)} (recorded: \${JSON.stringify(diff.current)})\`);
  }
  if (SENSITIVE_KEYS.length > 0) {
    console.log(\`Flagged as access-control-relevant (by the same sentence-embedding classifier RAPIDOR itself uses): \${SENSITIVE_KEYS.join(', ')}\`);
  }
  db.close();
}
`;
}

/** Writes the reproduction script to disk and returns its path, or undefined if writing failed (never throws: a report failing to generate must not break the crawl). */
export function writeReproductionScript(input: ReproductionInput): string | undefined {
  try {
    const dir = join(input.reportsDir, input.site);
    mkdirSync(dir, { recursive: true });
    const filePath = join(dir, `${input.id}.repro.ts`);

    const content = `// AUTO-GENERATED reproduction script for one flagged finding — output of the analysis pipeline,
// meant to be run directly by a human tester to confirm the finding, not an internal test of this
// project's own code.
//
// Finding id:       ${input.id}
// Site:              ${input.site}
// Reference (yours): ${input.referenceUrl}
// Candidate (theirs): ${input.candidateUrl}
// Motivation:        ${input.motivation.replace(/\n/g, ' ')}
//
// Run with: npx tsx ${filePath}
// (from the project root, so the relative imports below resolve)
//
// Caveat: the React-evidence section below re-reads ${input.dbPath} by the state/node ids recorded
// when this report was generated. If the crawler has run again since (clearOnStart wipes that db by
// default), that section will say so and skip itself gracefully — the live replay above it only
// needs network/browser access to the real site, so it stays reproducible regardless.
import { chromium } from 'playwright';

const REFERENCE_URL = ${literal(input.referenceUrl)};
const CANDIDATE_URL = ${literal(input.candidateUrl)};
const DB_PATH = ${literal(input.dbPath)};
const USER_DATA_DIR = ${literal(input.userDataDir ?? '')}; // '' = ephemeral profile (unauthenticated, unless the site needs no login)
const STATE_ID = ${literal(input.stateId)};
const REFERENCE_NODE_ID = ${literal(input.referenceNodeId)};
const CANDIDATE_NODE_ID = ${literal(input.candidateNodeId)};
const DIFFERENCES = ${literal(input.differences)};
const SENSITIVE_KEYS = ${literal(input.sensitiveKeys)};

${reactEvidenceSection(input)}

async function main() {
  const context = await chromium.launchPersistentContext(USER_DATA_DIR, { headless: false, channel: 'chromium' });
  const page = context.pages()[0] ?? await context.newPage();

  try {
${reproductionBody(input)}
  } finally {
    await context.close();
  }

  await checkReactEvidence();

  console.log('\\n--- to verify fully independently of this db ---');
  console.log(\`1. Open \${REFERENCE_URL} with RAPIDOR loaded in 'full' mode (see browser_extension/rapidor, config.js mode).\`);
  console.log(\`2. In its panel, find the component instance whose props carry the reference value, and the sibling instance for the candidate value.\`);
  console.log('3. Check that the properties listed above (OK/MISMATCH) genuinely differ the same way on the live page.');
}

await main();
process.exit(0);
`;

    writeFileSync(filePath, content);
    return filePath;
  } catch (err) {
    log.warning(`writeReproductionScript failed (finding ${input.id} still recorded in the db): ${(err as Error).message}`);
    return undefined;
  }
}
